// Fixtures for the things the original smoke tests could not reach: the
// COMPRESSED glTF a real pipeline exports, a USDZ, a point cloud, and the files
// that must fail with a sentence rather than a stack trace.
//
//   node verification/make-heavy-fixtures.mjs
//
// Small on purpose -- these are committed. The HEAVY model is generated by the
// check itself at run time (see check.mjs), because a few hundred MB of OBJ is
// not something a repository should carry.
import * as THREE from 'three';
import { USDZExporter } from 'three/addons/exporters/USDZExporter.js';
import { Document, NodeIO } from '@gltf-transform/core';
import { ALL_EXTENSIONS, KHRDracoMeshCompression, EXTMeshoptCompression } from '@gltf-transform/extensions';
import { reorder, quantize } from '@gltf-transform/functions';
import draco3d from 'draco3dgltf';
import { MeshoptEncoder, MeshoptDecoder } from 'meshoptimizer';
import { mkdir, writeFile } from 'node:fs/promises';

const DIR = new URL('./fixtures/', import.meta.url);
await mkdir(DIR, { recursive: true });
const out = name => new URL(name, DIR);

// A torus knot with enough triangles that compression actually does something.
function knotDocument() {
  // INDEXED, or neither compressor touches it: Draco skips non-indexed
  // primitives and Meshopt's reorder needs an index -- and a fixture that was
  // never compressed passes every "decoded the compressed file" check.
  const g = new THREE.TorusKnotGeometry(1, 0.3, 256, 32, 2, 3);
  const doc = new Document();
  const buffer = doc.createBuffer();
  const position = doc.createAccessor().setType('VEC3').setArray(new Float32Array(g.attributes.position.array)).setBuffer(buffer);
  const normal = doc.createAccessor().setType('VEC3').setArray(new Float32Array(g.attributes.normal.array)).setBuffer(buffer);
  const material = doc.createMaterial('knot').setBaseColorFactor([0.95, 0.35, 0.1, 1]).setRoughnessFactor(0.4);
  const indices = doc.createAccessor().setType('SCALAR').setArray(new Uint32Array(g.index.array)).setBuffer(buffer);
  const prim = doc.createPrimitive().setAttribute('POSITION', position).setAttribute('NORMAL', normal).setIndices(indices).setMaterial(material);
  const mesh = doc.createMesh('knot').addPrimitive(prim);
  doc.createScene('scene').addChild(doc.createNode('knot').setMesh(mesh));
  return doc;
}

const io = new NodeIO().registerExtensions(ALL_EXTENSIONS).registerDependencies({
  'draco3d.encoder': await draco3d.createEncoderModule(),
  'draco3d.decoder': await draco3d.createDecoderModule(),
  'meshopt.encoder': MeshoptEncoder, 'meshopt.decoder': MeshoptDecoder,
});

const dracoDoc = knotDocument();
dracoDoc.createExtension(KHRDracoMeshCompression).setRequired(true).setEncoderOptions({ method: KHRDracoMeshCompression.EncoderMethod.EDGEBREAKER });
await writeFile(out('knot-draco.glb'), await io.writeBinary(dracoDoc));

await MeshoptEncoder.ready;
const meshoptDoc = knotDocument();
await meshoptDoc.transform(reorder({ encoder: MeshoptEncoder }), quantize());
meshoptDoc.createExtension(EXTMeshoptCompression).setRequired(true).setEncoderOptions({ method: EXTMeshoptCompression.EncoderMethod.QUANTIZE });
await writeFile(out('knot-meshopt.glb'), await io.writeBinary(meshoptDoc));

// USDZ, through three's own exporter, so the importer is checked against a
// file it is known to have written.
const usdzScene = new THREE.Scene();
usdzScene.add(new THREE.Mesh(new THREE.BoxGeometry(1, 1, 1), new THREE.MeshStandardMaterial({ color: 0x3399ff })));
await writeFile(out('box.usdz'), await new USDZExporter().parseAsync(usdzScene));

// A point cloud: a PLY with vertices and no faces.
const points = [];
for (let i = 0; i < 20000; i++) {
  const t = i / 20000 * Math.PI * 2 * 7, r = 1 + 0.3 * Math.sin(t * 3);
  points.push(`${(r * Math.cos(t)).toFixed(4)} ${(i / 20000 * 2 - 1).toFixed(4)} ${(r * Math.sin(t)).toFixed(4)} 255 ${Math.round(128 + 127 * Math.sin(t))} 40`);
}
await writeFile(out('cloud.ply'), ['ply', 'format ascii 1.0', `element vertex ${points.length}`,
  'property float x', 'property float y', 'property float z',
  'property uchar red', 'property uchar green', 'property uchar blue', 'end_header', ...points, ''].join('\n'));

// Files that must FAIL, each with its own sentence.
await writeFile(out('broken.glb'), Buffer.from('this is not a binary gltf at all, just text pretending'));
await writeFile(out('renamed-blend.fbx'), Buffer.concat([Buffer.from('BLENDER-v300'), Buffer.alloc(64)]));
await writeFile(out('ancient.fbx'), '; FBX 6.1.0 project file\nFBXHeaderExtension:  {\n\tFBXHeaderVersion: 1003\n\tFBXVersion: 6100\n}\n');
await writeFile(out('scene.blend'), Buffer.concat([Buffer.from('BLENDER-v300'), Buffer.alloc(64)]));

console.log('fixtures: knot-draco.glb, knot-meshopt.glb, box.usdz, cloud.ply, broken.glb, renamed-blend.fbx, ancient.fbx, scene.blend');
